select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true)from q_test;
set local role authenticated;
do $$declare t record;c record;begin select * into t from q_test;select * into c from contesto_test;
 begin perform public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor);raise exception 'ASSERT: helper autore eseguibile dal client';exception when insufficient_privilege then null;end;
 perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'hr',t.hr,t.r1,'revoca',null,null,null,'TEST revoca propria');
 begin perform public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica2);raise exception 'ASSERT: revoca propria non rilevata';exception when serialization_failure then null;end;
end$$;
